#include <stdio.h>
#include <string.h>

int match(const char *s, const char *p) {
    if (*p == '*') {
        if (*(p + 1) == '*') {
            return match(s, p + 1);
        } else {
            do {
                if (match(s, p + 1))
                    return 1;
            } while (*s++);
            return 0;
        }
    }
    while (*s && *p) {
        if (*p == '?') {
            p++;
            s++;
        } else if (*p == '*') {
            return match(s, p) || match(s + 1, p);
        } else if (*s != *p)
            return 0;
        else {
            p++;
            s++;
        }
    }
    return !*s && !*p;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }
    const char *str = argv[1];
    const char *pattern = argv[2];
    if (match(str, pattern)) {
        printf("MATCH\n");
    } else {
        printf("NO_MATCH\n");
    }
    return 0;
}
